/**
 * Change the rank (depth, level) of headings.
 *
 * Does not shift past `h1` and `h6`.
 *
 * @param {Options | null | undefined} [options]
 *   Configuration (optional).
 * @returns
 *   Transform.
 */
export default function rehypeShiftHeading(options?: Options | null | undefined): (tree: Root) => undefined;
export type Root = import('hast').Root;
/**
 * Configuration.
 */
export type Options = {
    /**
     * Number to shift headings (default: `0`); can be negative to decrease
     * heading levels.
     */
    shift?: number | null | undefined;
};
